		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

// SendEndpoint represent one Send call.
// Deprecated: Use pkg/endpoint/cep.StreamSendEndpoint or pkg/endpoint/sep.StreamSendEndpoint instead.
type SendEndpoint func(stream streaming.Stream, message interface{}) (err error)

// SendMiddleware deal with input SendEndpoint and output SendEndpoint.
// Deprecated: Use pkg/endpoint/cep.StreamSendMiddleware or pkg/endpoint/sep.StreamSendMiddleware instead.
type SendMiddleware func(next SendEndpoint) SendEndpoint

// SendMiddlewareBuilder builds a middleware with information from a context.
// Deprecated: Use pkg/endpoint/cep.StreamSendMiddlewareBuilder or pkg/endpoint/sep.StreamSendMiddlewareBuilder instead.
type SendMiddlewareBuilder func(ctx context.Context) SendMiddleware

// SendChain connect middlewares into one middleware.
// Deprecated: Use pkg/endpoint/cep.StreamSendChain or pkg/endpoint/sep.StreamSendChain instead.
func SendChain(mws ...SendMiddleware) SendMiddleware {
	return func(next SendEndpoint) SendEndpoint {
		for i := len(mws) - 1; i >= 0; i-- {
			next = mws[i](next)
		}
		return next
	}
}

